import{_ as e,o as _,c as t,a3 as s}from"./chunks/framework.DdpBa4_E.js";const o="/ReadBooks/assets/image-019.BdY4KITM.jpg",p="/ReadBooks/assets/image-021.DE8BhTZw.jpg",h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"books/xialiu-shehui/58-自我主张派的阶层意识和生活满意度双双低下.md","filePath":"books/xialiu-shehui/58-自我主张派的阶层意识和生活满意度双双低下.md","lastUpdated":1794732511000}'),i={name:"books/xialiu-shehui/58-自我主张派的阶层意识和生活满意度双双低下.md"};function r(l,a,d,n,c,u){return _(),t("div",null,[...a[0]||(a[0]=[s('<h2 id="自我主张派的阶层意识和生活满意度双双低下" tabindex="-1">自我主张派的阶层意识和生活满意度双双低下 <a class="header-anchor" href="#自我主张派的阶层意识和生活满意度双双低下" aria-label="Permalink to &quot;自我主张派的阶层意识和生活满意度双双低下&quot;">​</a></h2><p>自我主张志向强烈并不意味着一定能够实现自我主张。虽然以追求自我主张为志向，却无法真正实现愿望的人，不仅对生活的满意度无法提高，而且低收入也使得他们的阶层意识日渐低下。</p><p>事实上，回答在生活当中重视自我主张的人（自我主张派）和没有作出如此回答的人（非自我主张派），如果比较两者的阶层意识，则自我主张派的人“下流”者居多（见表5-5）。此外，如果给生活满意度打分的话，自我主张派的人也很少有80分以上的（见表5-6）。</p><p>表5-5　团块次代中自我主张派与非自我主张派的阶层意识</p><p><img src="'+o+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所，e-FALCON共同实施的“欲求调查”</p><p>表5-6　团块次代中不同自我主张志向人群的生活满意度（过去、现在、将来）</p><p><img src="'+p+'" alt="" loading="lazy"></p><p>资料出处：Culture Studies研究所，e-FALCON共同实施的“欲求调查”</p><p>以追求自我主张为志向原本是一件好事，但如果过度地追求自我主张，会使得自己的阶层意识和生活满意度双双下降。</p><p>然而非常有趣的是，如果注意一下团块次代不同自我主张人群对于过去和将来的生活满意度，结果恰好相反。自我主张派的年轻人不论男女，很多都打80分以上。也就是说，在年轻的时候，靠自我主张来生活可以感到满足，可一旦过了30岁就不是那么回事了。不过他们一般都期望将来的生活满意度或许会再度提升。</p><p>这种期望会成为现实吗？还是就像梦一般地结束？这对于整个社会来说，是一个不容小觑的问题。</p>',12)])])}const f=e(i,[["render",r]]);export{h as __pageData,f as default};
